<script setup lang="ts">
import {computed,ref} from 'vue'
import {useCampus} from '../stores/campus'
import AppIcon from './AppIcon.vue'
const campus=useCampus(),network=computed(()=>campus.dashboard?.network||{}),traffic=computed(()=>network.value.primary_metric==='traffic'),devices=ref<any>(null),busy=ref(false),error=ref('')
function number(value:any){return value===null||value===undefined?'—':Number(value).toFixed(2)}
function clock(value:string){return value?value.slice(0,16).replace('T',' '):'尚未同步'}
async function loadDevices(){busy.value=true;error.value='';try{devices.value=await campus.networkDevices()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function onlineTime(value:any){const d=new Date(Number(value)*(Number(value)>1e12?1:1000));return Number.isNaN(d.getTime())?'时间未知':`${d.getMonth()+1}月${d.getDate()}日 ${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`}
</script>
<template><view class="network-detail"><view class="network-hero panel"><view class="network-hero-heading"><view><AppIcon name="wifi" :size="38"/><text>{{network.plan_label||'校园网'}}</text></view><text v-if="network.status==='stale'" class="network-cache">上次同步</text></view><text class="network-main-label">{{traffic?'剩余可用流量':'产品账户余额'}}</text><view class="network-main-value"><text v-if="!traffic" class="network-currency">¥</text>{{number(traffic?network.remaining_gb:network.balance)}}<text class="network-main-unit">{{traffic?'GB':'元'}}</text></view><view class="network-period"><AppIcon name="calendar" :size="28"/><view><text>{{network.period?.end?'本周期至 '+network.period.end:network.period?.state==='not_started'?'尚未开启计费周期':'周期信息尚未同步'}}</text><text v-if="network.period?.start">周期开始 {{network.period.start}}</text></view></view></view>
<view class="network-section-title"><text>流量与余额</text><text>{{network.unlimited?'不限量套餐':'演示计费方式'}}</text></view><view class="network-stats"><view class="panel"><text>本期已用</text><text>{{number(network.used_gb)}}<text> GB</text></text></view><view class="panel"><text>{{network.unlimited?'流量额度':'赠送流量'}}</text><text>{{network.unlimited?'不限量':number(network.gift_gb)}}<text v-if="!network.unlimited"> GB</text></text></view><view class="panel"><text>产品余额</text><text>{{number(network.balance)}}<text> 元</text></text></view><view class="panel"><text>{{network.wallet_balance!==null&&network.wallet_balance!==undefined?'电子钱包':'套餐内流量'}}</text><text>{{network.wallet_balance!==null&&network.wallet_balance!==undefined?number(network.wallet_balance):network.base_quota_gb===null?(network.unlimited?'不限量':'—'):number(network.base_quota_gb)}}<text>{{network.wallet_balance!==null&&network.wallet_balance!==undefined?' 元':network.base_quota_gb===null?'':' GB'}}</text></text></view></view>
<view class="network-info panel"><view><text>套餐名称</text><text>{{network.plan_name||'尚未同步'}}</text></view><view v-if="network.monthly_price!==null&&network.monthly_price!==undefined"><text>周期费用</text><text>{{network.monthly_price}} 元</text></view><view v-if="network.device_limit"><text>可同时在线</text><text>{{network.device_limit}} 台设备</text></view><view><text>周期到期</text><text>{{network.period?.end||'尚未开启'}}</text></view><view><text>采集时间</text><text>{{clock(network.observed_at)}}</text></view></view><view v-if="traffic&&network.remaining_gb!==null&&network.remaining_gb!==undefined" class="network-formula panel"><text>可用流量组成</text><view><text>套餐 {{number(network.base_quota_gb)}} GB</text><text>+ 赠送 {{number(network.gift_gb)}} GB</text><text>+ 余额折合 {{number(network.balance_traffic_gb)}} GB</text><text>− 已用 {{number(network.used_gb)}} GB</text></view><text>虚构数据，仅供前端展示</text></view>
<view class="network-devices panel"><view class="network-device-heading"><view><AppIcon name="wifi" :size="31"/><text>在线设备</text></view><text @click="loadDevices">{{busy?'查询中…':devices?'刷新 ›':'查看 ›'}}</text></view><text v-if="error" class="network-device-note">{{error}}</text><text v-else-if="devices&&!devices.items.length" class="network-device-note">当前没有在线设备</text><view v-for="(device,i) in devices?.items||[]" :key="i" class="network-device"><view class="network-device-icon"><AppIcon name="user" :size="30"/></view><view><text>{{device.name||'校园网终端'}}</text><text>{{device.ip}} · {{onlineTime(device.since)}}</text></view></view></view><button class="network-refresh" :loading="campus.checking" @click="campus.checkServer">刷新校园网信息</button></view></template>
<style scoped lang="scss">
.panel{background:var(--panel);border-radius:30rpx;box-shadow:0 6rpx 28rpx #3f81ba04}.network-hero{padding:30rpx;background:linear-gradient(135deg,#e6f2ff,#f8fcff);color:#193652;overflow:hidden}.network-hero-heading{display:flex;justify-content:space-between;align-items:center}.network-hero-heading>view{display:flex;align-items:center;gap:13rpx;font-size:25rpx;font-weight:600}.network-cache{font-size:18rpx;color:#879db7;background:#dbeafa;padding:7rpx 12rpx;border-radius:10rpx}.network-main-label{display:block;color:#7d96af;font-size:23rpx;margin-top:35rpx}.network-main-value{font-size:72rpx;font-weight:750;margin-top:12rpx;letter-spacing:-2rpx}.network-currency{font-size:34rpx;margin-right:9rpx}.network-main-unit{font-size:29rpx;font-weight:500;letter-spacing:0;margin-left:10rpx}.network-period{display:flex;align-items:center;gap:13rpx;border-top:1rpx solid #cadff2;padding-top:23rpx;margin-top:28rpx;font-size:23rpx;color:#547a9f}.network-period text{display:block}.network-period text+text{font-size:19rpx;color:#8ba2ba;margin-top:7rpx}.network-section-title{display:flex;justify-content:space-between;align-items:center;margin:30rpx 5rpx 18rpx;font-size:28rpx;font-weight:600}.network-section-title>text+text{font-size:19rpx;color:var(--muted);font-weight:400}.network-stats{display:grid;grid-template-columns:1fr 1fr;gap:17rpx}.network-stats>view{padding:25rpx}.network-stats>view>text{display:block;font-size:22rpx;color:var(--muted)}.network-stats>view>text+text{font-size:33rpx;font-weight:650;color:var(--ink);margin-top:16rpx}.network-stats>view>text>text{font-size:20rpx;font-weight:400;color:var(--muted)}.network-info{padding:3rpx 27rpx;margin-top:24rpx}.network-info>view{display:flex;align-items:flex-start;justify-content:space-between;padding:24rpx 0;gap:28rpx;border-bottom:1rpx solid var(--line);font-size:23rpx}.network-info>view:last-child{border:0}.network-info>view>text:first-child{flex-shrink:0;color:var(--muted)}.network-info>view>text+text{text-align:right;line-height:1.6}.network-formula{padding:27rpx;margin-top:24rpx}.network-formula>text{font-size:25rpx;font-weight:600}.network-formula>view{display:grid;grid-template-columns:1fr 1fr;gap:14rpx;margin:22rpx 0;font-size:22rpx;color:var(--muted)}.network-formula>text:last-child{display:block;font-size:19rpx;font-weight:400;color:var(--muted);line-height:1.7}.network-devices{padding:27rpx;margin-top:24rpx}.network-device-heading{display:flex;justify-content:space-between;align-items:center;font-size:25rpx;font-weight:600}.network-device-heading>view{display:flex;align-items:center;gap:11rpx}.network-device-heading>text{font-size:22rpx;font-weight:400;color:#438ee9}.network-device{display:flex;gap:15rpx;align-items:center;padding-top:23rpx}.network-device-icon{background:var(--soft);width:61rpx;height:61rpx;border-radius:18rpx;display:flex;align-items:center;justify-content:center}.network-device text{display:block;font-size:24rpx}.network-device text+text{font-size:19rpx;color:var(--muted);margin-top:7rpx;line-height:1.7}.network-device-note{display:block;color:var(--muted);font-size:22rpx;margin-top:20rpx}.network-refresh{background:#287bf5;color:#fff;border-radius:22rpx;font-size:25rpx;height:86rpx;line-height:86rpx;margin-top:25rpx}
</style>
